-- Initial Supabase schema generated from backend/ACHIEVA_BACKEND/prisma/schema.prisma.
-- The Prisma init migration was used as a baseline, but this file follows the
-- current Prisma schema where the two differ.

CREATE TYPE "UserRole" AS ENUM ('admin', 'student', 'teacher');
CREATE TYPE "UserStatus" AS ENUM ('active', 'inactive');
CREATE TYPE "ModuleStatus" AS ENUM ('published', 'archived');
CREATE TYPE "QuestionType" AS ENUM ('multiple_choice', 'true_false', 'short_answer');

CREATE TABLE "courses" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "title" varchar(255) NOT NULL,
    "description" text,
    "image" varchar(255),
    "created_at" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "courses_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "profiles" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "first_name" varchar(100) NOT NULL,
    "middle_name" varchar(100) NOT NULL,
    "last_name" varchar(255) NOT NULL,
    "bio" text,
    "email" varchar(100) NOT NULL,
    "age" integer NOT NULL,
    "trial" text,
    "username" varchar(100),
    "password" varchar(255) NOT NULL,
    "role" "UserRole" NOT NULL,
    "university" varchar(255),
    "purpose" varchar(255),
    "date_of_examination" timestamp(3),
    "created_at" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamp(3) DEFAULT CURRENT_TIMESTAMP,
    "status" "UserStatus" NOT NULL DEFAULT 'active',
    "profile_image" varchar(255),
    "course_id" integer,
    "name" text NOT NULL,
    "emailVerified" boolean NOT NULL DEFAULT false,
    "image" text,
    CONSTRAINT "users_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "sessions" (
    "id" varchar(255) NOT NULL,
    "user_id" integer,
    "ip_address" varchar(45),
    "user_agent" text,
    "payload" text NOT NULL,
    "last_activity" integer NOT NULL,
    "expiresAt" timestamp(3) NOT NULL,
    "token" text NOT NULL,
    "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "sessions_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "tasks" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "task_name" varchar(255) NOT NULL,
    "description" text NOT NULL,
    "user_id" integer NOT NULL,
    "isDone" boolean NOT NULL DEFAULT false,
    "deadline" timestamp(3) NOT NULL,
    "created_at" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "tasks_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "progress_days" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "user_id" integer NOT NULL,
    "activity_date" date NOT NULL,
    "is_active" boolean NOT NULL DEFAULT true,
    "created_at" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "progress_days_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "subjects" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "title" varchar(255) NOT NULL,
    "course_id" integer NOT NULL,
    "description" text,
    "image" varchar(255),
    "day_subject" varchar(255),
    "created_at" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "subjects_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "modules" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "title" varchar(255) NOT NULL,
    "description" text,
    "user_id" integer,
    "created_at" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "file" varchar(255),
    "image" varchar(255),
    "status" "ModuleStatus" NOT NULL DEFAULT 'published',
    "subject_id" integer,
    CONSTRAINT "modules_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "topics" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "title" varchar(255) NOT NULL,
    "subject_id" integer NOT NULL,
    "content" text,
    "video_link" varchar(255),
    "created_at" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "topics_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "quizzes" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "title" varchar(255) NOT NULL,
    "description" text,
    "created_at" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "subject_id" integer NOT NULL,
    CONSTRAINT "quizzes_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "questions" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "quiz_id" integer NOT NULL,
    "question_text" text NOT NULL,
    "question_type" "QuestionType" NOT NULL,
    "image_path" varchar(255),
    "correct_description" text,
    "notes" text,
    CONSTRAINT "questions_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "choices" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "question_id" integer NOT NULL,
    "choice_text" varchar(255) NOT NULL,
    "image" varchar(255),
    "is_correct" boolean NOT NULL DEFAULT false,
    CONSTRAINT "choices_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "quiz_attempts" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "quiz_id" integer NOT NULL,
    "student_id" integer NOT NULL,
    "score" decimal(5, 2),
    "attempted_at" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "answer" json,
    "no_of_attempt" integer NOT NULL,
    "summary" json,
    CONSTRAINT "quiz_attempts_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "answers" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "attempt_id" integer NOT NULL,
    "question_id" integer NOT NULL,
    "answer_text" text,
    "choice_id" integer,
    CONSTRAINT "answers_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "mnemonics" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "subject_id" integer NOT NULL,
    "title" varchar(255) NOT NULL,
    "file_path" varchar(255),
    "description" text,
    "created_at" timestamp(3),
    "updated_at" timestamp(3),
    CONSTRAINT "mnemonics_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "procedures" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "title" varchar(255) NOT NULL,
    "subject_id" integer NOT NULL,
    "file_path" varchar(255),
    "created_at" timestamp(3),
    "updated_at" timestamp(3),
    CONSTRAINT "procedures_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "abbreviations" (
    "id" integer GENERATED BY DEFAULT AS IDENTITY,
    "short_form" varchar(100) NOT NULL,
    "full_form" varchar(255) NOT NULL,
    "subject_id" integer,
    "created_at" timestamp(3),
    "updated_at" timestamp(3),
    CONSTRAINT "abbreviations_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "account" (
    "id" text NOT NULL,
    "accountId" text NOT NULL,
    "providerId" text NOT NULL,
    "userId" integer NOT NULL,
    "accessToken" text,
    "refreshToken" text,
    "idToken" text,
    "accessTokenExpiresAt" timestamp(3),
    "refreshTokenExpiresAt" timestamp(3),
    "scope" text,
    "password" text,
    "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "account_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "verification" (
    "id" text NOT NULL,
    "identifier" text NOT NULL,
    "value" text NOT NULL,
    "expiresAt" timestamp(3) NOT NULL,
    "createdAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "verification_pkey" PRIMARY KEY ("id")
);

