CREATE OR REPLACE FUNCTION public.handle_new_auth_user()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    metadata jsonb;
    first_name text;
    middle_name text;
    last_name text;
    resolved_name text;
    resolved_role "UserRole";
    resolved_age integer;
BEGIN
    metadata := COALESCE(NEW.raw_user_meta_data, '{}'::jsonb);
    first_name := COALESCE(NULLIF(metadata ->> 'first_name', ''), '');
    middle_name := COALESCE(NULLIF(metadata ->> 'middle_name', ''), '');
    last_name := COALESCE(NULLIF(metadata ->> 'last_name', ''), '');
    resolved_name := COALESCE(NULLIF(metadata ->> 'name', ''), NULLIF(trim(concat_ws(' ', first_name, last_name)), ''), NEW.email, '');
    resolved_role := CASE
        WHEN metadata ->> 'role' IN ('admin', 'student', 'teacher') THEN (metadata ->> 'role')::"UserRole"
        ELSE 'student'::"UserRole"
    END;
    resolved_age := CASE
        WHEN COALESCE(metadata ->> 'age', '') ~ '^[0-9]+$' THEN (metadata ->> 'age')::integer
        ELSE 0
    END;

    INSERT INTO public."users" (
        "first_name",
        "middle_name",
        "last_name",
        "bio",
        "email",
        "age",
        "trial",
        "username",
        "password",
        "role",
        "university",
        "purpose",
        "status",
        "profile_image",
        "course_id",
        "name",
        "emailVerified",
        "image"
    ) VALUES (
        first_name,
        middle_name,
        last_name,
        NULLIF(metadata ->> 'bio', ''),
        COALESCE(NEW.email, metadata ->> 'email'),
        resolved_age,
        NULLIF(metadata ->> 'trial', ''),
        NULLIF(metadata ->> 'username', ''),
        '',
        resolved_role,
        NULLIF(metadata ->> 'university', ''),
        NULLIF(metadata ->> 'purpose', ''),
        'active'::"UserStatus",
        NULLIF(metadata ->> 'profile_image', ''),
        CASE WHEN COALESCE(metadata ->> 'courseId', '') ~ '^[0-9]+$' THEN (metadata ->> 'courseId')::integer ELSE NULL END,
        resolved_name,
        NEW.email_confirmed_at IS NOT NULL,
        NULLIF(metadata ->> 'image', '')
    )
    ON CONFLICT ("email") DO UPDATE SET
        "emailVerified" = EXCLUDED."emailVerified",
        "updated_at" = CURRENT_TIMESTAMP;

    RETURN NEW;
END;
$$;

CREATE TRIGGER "on_auth_user_created"
AFTER INSERT ON auth.users
FOR EACH ROW EXECUTE FUNCTION public.handle_new_auth_user();

